package main
import("bytes";"encoding/binary";"encoding/json";"fmt";"os";"reflect";"github.com/ethereum/go-ethereum/accounts/abi";"github.com/ethereum/go-ethereum/crypto")
type Config struct{Domain [32]byte;Schema uint32;RuntimeHash [32]byte;BootstrapRoot [32]byte;Artifact [32]byte;RootDomain [32]byte;RootKind uint8;EntryClass string;Entry string;ArgsCommitment [32]byte;Args []int32;SeedRoot [32]byte;LimitsHash [32]byte}
func main(){ names:=[]string{"domain","schema","runtimeHash","bootstrapRoot","artifact","rootDomain","rootKind","entryClass","entry","argsCommitment","args","seedRoot","limitsHash"};types:=[]string{"bytes32","uint32","bytes32","bytes32","bytes32","bytes32","uint8","string","string","bytes32","int32[]","bytes32","bytes32"};var components []abi.ArgumentMarshaling;var flat abi.Arguments;for i,n:=range names{components=append(components,abi.ArgumentMarshaling{Name:n,Type:types[i]});t,e:=abi.NewType(types[i],"",nil);must(e);flat=append(flat,abi.Argument{Type:t})};tuple,e:=abi.NewType("tuple","",components);must(e);targs:=abi.Arguments{{Type:tuple}};var all bytes.Buffer
for i:=0;i<512;i++{h:=func(n string)[32]byte{return crypto.Keccak256Hash([]byte(fmt.Sprintf("p55-%d-%s",i,n)))};c:=Config{Domain:h("d"),Schema:uint32(i),RuntimeHash:h("r"),BootstrapRoot:h("b"),Artifact:h("a"),RootDomain:h("dr"),RootKind:uint8(i),EntryClass:string(bytes.Repeat([]byte{'C'},i%97)),Entry:"main",ArgsCommitment:h("args"),SeedRoot:h("seed"),LimitsHash:h("limits")};if i%4==1{c.EntryClass="a\x00é中";c.Entry="\x00"};for j:=0;j<i%17;j++{c.Args=append(c.Args,int32(uint32(i*100003+j)*0x1234abcd))};if i%5==0{c.Args=[]int32{-2147483648,-1,0,1,2147483647}};rv:=reflect.ValueOf(c);vals:=make([]interface{},rv.NumField());for j:=range vals{vals[j]=rv.Field(j).Interface()};a,e:=flat.Pack(vals...);must(e);b,e:=targs.Pack(c);must(e);if len(b)<32||binary.BigEndian.Uint64(b[24:32])!=32||!bytes.Equal(b[32:],a){panic(fmt.Sprintf("tuple flatten mismatch %d",i))};all.Write(crypto.Keccak256(a))};out,_:=json.MarshalIndent(map[string]interface{}{"status":"PASS","generatedCases":512,"flatTuple":"13 original fields in exact order","dynamicCases":"empty/nonempty/NUL/UTF8 strings, signed int32 extrema and variable arrays","proof":"abi.encode(single dynamic struct)[32:] equals abi.encode(original fields...)","aggregateKeccak":crypto.Keccak256Hash(all.Bytes()),"noOriginalInputs":true},"","  ");fmt.Println(string(out));if len(os.Args)>1{must(os.WriteFile(os.Args[1],append(out,'\n'),0600))}}
func must(e error){if e!=nil{panic(e)}}
